 static final String B="dev/zomboid/hordes/";static final Map<String,Integer> hits=new TreeMap<>();static void hit(String n){hits.merge(n,1,Integer::sum);}static MethodInsnNode call(String owner,String n,String d){return new MethodInsnNode(INVOKESTATIC,owner,n,d,false);}static void args(InsnList x,int...a){for(int n:a)x.add(new VarInsnNode(ALOAD,n));}static void clear(MethodNode m){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;}
 static void tail(MethodNode m,String owner,String method,String desc,int...a){for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==RETURN){InsnList x=new InsnList();args(x,a);x.add(call(owner,method,desc));m.instructions.insertBefore(i,x);hit(method);}}
 static void boolGuard(MethodNode m,String owner,String method,String desc,int...a){InsnList x=new InsnList();LabelNode next=new LabelNode();args(x,a);x.add(call(owner,method,desc));x.add(new JumpInsnNode(IFEQ,next));x.add(new InsnNode(RETURN));x.add(next);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);hit(method);}
 static byte[] patch(byte[]bytes,String kind){ClassNode c=new ClassNode();new ClassReader(bytes).accept(c,0);int before=hits.values().stream().mapToInt(Integer::intValue).sum();for(MethodNode m:c.methods){
 if(kind.equals("hordes")){
 if(c.name.equals(B+"ZoneSettings")&&m.name.equals("install"))tail(m,B+"AmbientSettings47","install","(Ljava/util/Map;Ljava/util/Map;Ljava/util/Map;Ljava/util/Map;)V",0,1,2,3);
 if(c.name.equals(B+"ZoneSettings")&&m.name.equals("applied"))tail(m,B+"AmbientSettings47","applied","()V");
 if(c.name.equals(B+"ApocalypseSettings")&&m.name.equals("preset")){for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==RETURN){InsnList x=new InsnList();args(x,0);x.add(new VarInsnNode(ILOAD,1));x.add(call(B+"AmbientSettings47","preset","(Ljava/util/Map;I)V"));m.instructions.insertBefore(i,x);hit("ambient_preset");}}
 if(c.name.equals(B+"WorldTuning")&&m.name.equals("checked")){InsnList x=new InsnList();args(x,0);x.add(new VarInsnNode(DLOAD,1));x.add(call(B+"AmbientSettings47","validate","(Ljava/lang/String;D)V"));m.instructions.insert(x);hit("integer_validation");}
 if(c.name.equals(B+"WorldTuning")&&m.name.equals("batch")){InsnList x=new InsnList();args(x,0);x.add(call(B+"AmbientSettings47","validateBatch","(Ljava/util/Map;)V"));m.instructions.insert(x);hit("atomic_validation");}
 if(c.name.equals(B+"ChunkPopulation")&&m.name.equals("populate")){clear(m);args(m.instructions,0,1,2);m.instructions.add(new VarInsnNode(LLOAD,3));m.instructions.add(call(B+"Population47","populate",m.desc));m.instructions.add(new InsnNode(IRETURN));hit("population_3x3");}
 if(c.name.equals(B+"HordeEvents")&&m.name.equals("serverTick")){InsnList x=new InsnList();args(x,0);x.add(call(B+"Heat47","server","(Ljava/lang/Object;)V"));m.instructions.insert(x);hit("heat_tick");}
 if(c.name.equals(B+"HordeEvents")&&m.name.equals("recordGunShot")){InsnList x=new InsnList();args(x,0);x.add(new VarInsnNode(DLOAD,1));x.add(call(B+"Heat47","gun","(Ljava/lang/Object;D)V"));m.instructions.insert(x);hit("heat_gun");}
 if(c.name.equals(B+"HordeEvents")&&m.name.equals("quietAction")){for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof FieldInsnNode f&&f.getOpcode()==PUTFIELD&&f.name.equals("score")){InsnList x=new InsnList();args(x,0);x.add(call(B+"Heat47","action","(Ljava/lang/Object;)V"));m.instructions.insert(i,x);hit("heat_action");}}

 if(c.name.equals(B+"client/AdminScreen")&&m.name.equals("mouseScrolled")){InsnList x=new InsnList();LabelNode next=new LabelNode();args(x,0);x.add(new VarInsnNode(DLOAD,1));x.add(new VarInsnNode(DLOAD,3));x.add(new VarInsnNode(DLOAD,7));x.add(call(B+"SimplePanel","wheel","(Ljava/lang/Object;DDD)Z"));x.add(new JumpInsnNode(IFEQ,next));x.add(new InsnNode(ICONST_1));x.add(new InsnNode(IRETURN));x.add(next);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);hit("panel_scroll");}
 if(c.name.equals(B+"AdminNetwork")&&m.name.equals("register")){for(AbstractInsnNode i:m.instructions)if(i instanceof LdcInsnNode l&&l.cst.equals("40")){l.cst="47";hit("protocol47");}}
 if(c.name.equals(B+"client/AdminScreen")&&m.name.equals("<clinit>")){for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new FieldInsnNode(GETSTATIC,c.name,"KEYS","[[Ljava/lang/String;"));x.add(new LdcInsnNode("KEYS"));x.add(call(B+"SimplePanel","advancedRows","([[Ljava/lang/String;Ljava/lang/String;)[[Ljava/lang/String;"));x.add(new FieldInsnNode(PUTSTATIC,c.name,"KEYS","[[Ljava/lang/String;"));m.instructions.insertBefore(i,x);hit("advanced_population_alias");}}
 if(c.name.equals(B+"client/AdminScreen")&&m.name.equals("receive"))boolGuard(m,B+"HeatClient47","receive","(Ljava/lang/String;)Z",0);
 }
 if(kind.equals("quiet")&&c.name.equals("dev/zomboid/scavenging/Loot")&&m.name.equals("bonus"))boolGuard(m,"dev/zomboid/scavenging/AmbientBridge47","bonus","(Ldev/zomboid/scavenging/Search$Target;Ljava/lang/Object;)Z",0,1);
 }
 if(kind.equals("hordes")&&c.name.equals(B+"client/AdminScreen")){for(String method:new String[]{"mouseClicked","mouseDragged","mouseReleased"}){boolean dragging=method.equals("mouseDragged"),release=method.equals("mouseReleased");String desc=dragging?"(DDIDD)Z":"(DDI)Z";MethodNode m=new MethodNode(ACC_PUBLIC,method,desc,null,null);args(m.instructions,0);if(!release){m.instructions.add(new VarInsnNode(DLOAD,1));m.instructions.add(new VarInsnNode(DLOAD,3));m.instructions.add(new VarInsnNode(ILOAD,5));}m.instructions.add(call(B+"SimplePanel",release?"release":dragging?"drag":"click",release?"(Ljava/lang/Object;)Z":"(Ljava/lang/Object;DDI)Z"));LabelNode next=new LabelNode();m.instructions.add(new JumpInsnNode(IFEQ,next));m.instructions.add(new InsnNode(ICONST_1));m.instructions.add(new InsnNode(IRETURN));m.instructions.add(next);m.instructions.add(new FrameNode(F_SAME,0,null,0,null));args(m.instructions,0);m.instructions.add(new VarInsnNode(DLOAD,1));m.instructions.add(new VarInsnNode(DLOAD,3));m.instructions.add(new VarInsnNode(ILOAD,5));if(dragging){m.instructions.add(new VarInsnNode(DLOAD,6));m.instructions.add(new VarInsnNode(DLOAD,8));}m.instructions.add(new MethodInsnNode(INVOKESPECIAL,c.superName,method,desc,false));m.instructions.add(new InsnNode(IRETURN));m.maxLocals=dragging?10:6;c.methods.add(m);hit(method);}}
 if(hits.values().stream().mapToInt(Integer::intValue).sum()==before)return bytes;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static byte[] event(String name,String type,String owner,String method,boolean client){ClassWriter w=new ClassWriter(0);w.visit(V21,ACC_PUBLIC,B+name,null,"java/lang/Object",null);AnnotationVisitor a=w.visitAnnotation("Lnet/neoforged/fml/common/EventBusSubscriber;",true);a.visit("modid","zomboid_hordes");if(client){AnnotationVisitor arr=a.visitArray("value");arr.visitEnum(null,"Lnet/neoforged/api/distmarker/Dist;","CLIENT");arr.visitEnd();}a.visitEnd();MethodVisitor m=w.visitMethod(ACC_PUBLIC|ACC_STATIC,method,"(L"+type+";)V",null,null);AnnotationVisitor sub=m.visitAnnotation("Lnet/neoforged/bus/api/SubscribeEvent;",true);if(name.equals("PopulationEvents47"))sub.visitEnum("priority","Lnet/neoforged/bus/api/EventPriority;","HIGHEST");sub.visitEnd();m.visitCode();m.visitVarInsn(ALOAD,0);m.visitMethodInsn(INVOKESTATIC,B+owner,method,"(Ljava/lang/Object;)V",false);m.visitInsn(RETURN);m.visitMaxs(1,1);m.visitEnd();w.visitEnd();return w.toByteArray();}
 public static void main(String[]a)throws Exception{Map<String,byte[]>e=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry n:Collections.list(z.entries())){byte[]b=z.getInputStream(n).readAllBytes();e.put(n.getName(),n.getName().endsWith(".class")?patch(b,a[3]):b);}}try(var walk=Files.walk(Path.of(a[2]))){for(Path p:walk.filter(p->p.toString().endsWith(".class")).toList())e.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}
 if(a[3].equals("hordes")){e.put(B+"HeatExplosionEvents47.class",event("HeatExplosionEvents47","net/neoforged/neoforge/event/level/ExplosionEvent$Detonate","Heat47","explosion",false));e.put(B+"PopulationEvents47.class",event("PopulationEvents47","net/neoforged/neoforge/event/entity/EntityJoinLevelEvent","Population47","join",false));e.put(B+"HeatScreenEvents47.class",event("HeatScreenEvents47","net/neoforged/neoforge/client/event/ScreenEvent$Render$Post","HeatClient47","render",true));e.put(B+"EnvironmentStop47.class",event("EnvironmentStop47","net/neoforged/neoforge/event/server/ServerStoppedEvent","Population47","clear",false));}
 for(var en:e.entrySet())if(en.getKey().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(en.getValue()).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var n:e.entrySet()){ZipEntry en=new ZipEntry(n.getKey());en.setTime(0);z.putNextEntry(en);z.write(n.getValue());z.closeEntry();}}System.out.println(a[3]+" "+hits);}
